import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';

// Load environment configuration generated by setup.ts
const env = JSON.parse(open('./k6-env.json'));

const firstAttemptCreated = new Counter('first_attempt_created');
const replayedMatches = new Counter('replayed_matches');
const replayServerErrors = new Rate('replay_server_errors');
const replayDuration = new Trend('replay_duration_ms');

export const options = {
  scenarios: {
    idempotent_replay: {
      executor: 'per-vu-iterations',
      vus: 100,
      iterations: 1,
      maxDuration: '45s',
    },
  },
  thresholds: {
    // Rubric requirement: creates 1 bill, deducts stock once, no 500s
    http_req_duration: ['p(95)<500'],
    replay_server_errors: ['rate==0'],
  },
};

function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

export default function () {
  sleep(Math.random() * 0.15);

  const url = `${env.baseUrl}/api/v1/sales`;
  const saleId = `sale-replay-${generateUUID()}`;
  const idemKey = `idem-k6-replay-vu-${__VU}-${Date.now()}`;

  // Use one of the 1000-stock catalogue products so stock won't run out
  const targetProduct = env.products ? env.products[1] : 'p_1';

  const payload = JSON.stringify({
    id: saleId,
    subtotal: 100.0,
    discount: 0.0,
    total: 100.0,
    paymentMethod: 'เงินสด',
    items: [
      {
        productId: targetProduct,
        name: 'Catalogue Part',
        qty: 1,
        price: 100.0,
      },
    ],
  });

  const params = {
    headers: {
      Authorization: `Bearer ${env.posToken}`,
      'Idempotency-Key': idemKey,
      'Content-Type': 'application/json',
      Accept: 'application/json',
    },
    tags: { name: 'PostSalesIdempotencyReplay' },
  };

  let initialReceiptNo = null;

  // Send the identical request 5 times in a row with the exact same Idempotency-Key
  for (let attempt = 1; attempt <= 5; attempt++) {
    const res = http.post(url, payload, params);
    replayDuration.add(res.timings.duration);

    if (res.status >= 500) {
      replayServerErrors.add(true);
    } else {
      replayServerErrors.add(false);
    }

    if (attempt === 1) {
      check(res, {
        'attempt 1 is 201 Created': (r) => r.status === 201,
      });
      if (res.status === 201) {
        firstAttemptCreated.add(1);
        try {
          const body = JSON.parse(res.body);
          initialReceiptNo = body.data.receiptNo;
        } catch {}
      }
    } else {
      // Attempts 2 to 5 should return success (200 or 201) with the EXACT same receiptNo
      const isOk = res.status === 200 || res.status === 201;
      let matchesReceipt = false;
      try {
        const body = JSON.parse(res.body);
        matchesReceipt = body.data && body.data.receiptNo === initialReceiptNo;
      } catch {}

      if (isOk && matchesReceipt) {
        replayedMatches.add(1);
      }

      check(res, {
        'replay attempt returns 200/201': () => isOk,
        'replay receipt matches attempt 1': () => matchesReceipt,
      });
    }

    sleep(0.05);
  }
}
